	loading = true;
	error = null;

	try {
		const [tasksResponse, inboxResponse, obsResponse, validationResult, agentStatusResult] =
			await Promise.all([
				fetchTasks({ limit: 1000 }),
				fetchInbox({ limit: 0 }),
				fetchObservations({ resolved: false }),
